"이름표를 달고 한참 서 있었지만 아무도 말을 걸지 않아 괜히 쓴 참가비만 아깝게 느껴졌다":"名札をつけてずいぶん立っていたが誰も話しかけてくれず、むだに払った参加費がもったいなく感じた",
"이불 속에서 손전등으로 책을 읽다가 건전지가 나갈 때까지 마지막 장을 놓지 못했다":"布団の中で懐中電灯で本を読み、電池が切れるまで最後の章を手放せなかった",
"이불 속에서 손전등을 켜고 물고기 그림책을 펴 보다가 파란 바다 쪽에서 오래 머물렀다":"布団の中で懐中電灯をつけて魚の絵本を開き、青い海のページに長くとどまった",
"이불 속에서 휴대폰을 잠깐 본다는 게 두 시간이 훌쩍 지나, 일어났을 때 머리만 더 무거웠다":"布団の中でスマホをちょっと見るつもりが二時間もたち、起きたときは頭だけ重くなっていた",
"이불을 둘러쓰고 동굴 탐험대가 되어, 손전등 하나로 방 안 구석구석을 비추고 다녔다":"布団をかぶって洞窟探検隊になり、懐中電灯一つで部屋の隅々を照らして回った",
"이사 가는 날 짐 사이에서 들고 나온 소설을 이삿짐 트럭 안에서 끝까지 읽었다":"引っ越しの日、荷物の間から取り出した小説を、引っ越しのトラックの中で最後まで読んだ",
"이사 짐을 풀다 나온 아이 적 그림책을 바닥에 주저앉아 쪽마다 넘겨 보았다":"引っ越しの荷ほどきで出てきた子どものころの絵本を、床に座り込んでページごとにめくった",
"이어폰 없이 걸으며 새소리를 하나하나 구분하려 해 보았는데 세 가지까지 이름을 붙일 수 있었다":"イヤホンなしで歩きながら鳥の声を一つずつ聞き分けようとしたら、三種類まで名前をつけられた",
"이어폰에서 흘러나온 빠른 노래에 발을 맞춰, 운동장 트랙을 숨이 차오를 때까지 여덟 바퀴 돌았다":"イヤホンから流れる速い曲に足を合わせ、運動場のトラックを息が上がるまで八周した",
"이웃 노인이 내가 쓰던 연장을 한번 만져 보더니, 이렇게 쓰는 거냐며 어설프게 흉내를 냈다":"近所のお年寄りが私の使っていた道具に一度触れて、こう使うのかと、ぎこちなくまねをした",
"이웃 농사일을 틈틈이 도와 주고 품삯 대신 받은 자루를 부엌 한쪽에 가지런히 쌓아 두었다":"近所の農作業をときどき手伝い、手間賃の代わりにもらった袋を台所の隅にきちんと積んでおいた",
"이웃 동네 사람들과 땀에 젖은 첫 연습 경기를 뛰고, 끝난 뒤 둘러앉아 먹은 얼음물이 달았다":"隣町の人たちと汗びっしょりで初めての練習試合をし、終わってから輪になって飲んだ氷水が甘かった",
"이웃 마을로 떠난 동료에게 안부를 물었더니 새 일터의 창가 풍경을 소상히 들려주었다":"隣の村へ移った同僚に様子を尋ねると、新しい職場の窓辺の景色を詳しく聞かせてくれた",
"이웃 사람 손을 잡아 연장 쥐는 법을 바로잡아 주자, 고개를 끄덕이며 한 번 더 해 보았다":"近所の人の手を取って道具の握り方を直してやると、うなずいてもう一度やってみた",
"이웃 아이가 가져온 부침개를 식탁에 올려놓고 둘러앉아 먹다 보니 한 접시가 금세 비었다":"近所の子が持ってきたチヂミを食卓にのせて、輪になって食べているうちに、一皿がすぐ空になった",
"이웃 아주머니가 가져온 낡은 악기를 같이 손봐 주고, 소리가 나던 순간 서로 얼굴을 쳐다보았다":"近所のおばさんが持ってきた古い楽器を一緒に手入れして、音が出た瞬間に互いの顔を見合わせた",
"이웃 청년이 찾아와 고장 난 물건을 같이 고쳐 보자고 해서, 손끝을 맞대고 요령을 보여 주었다":"近所の青年が訪ねてきて、壊れた物を一緒に直そうと言うので、指先を合わせてコツを見せた",
"이웃과 마당 평상에 걸터앉아 삶은 감자를 나누며 아이들 크는 이야기로 해가 넘어갔다":"近所の人と庭の縁台に腰かけて、ゆでたじゃがいもを分け合い、子どもの成長の話をするうちに日が暮れた",
"이웃이 부드럽게 푹 끓인 죽을 한 숟갈씩 나눠 주고 내 그릇이 비는 걸 지켜보았다":"近所の人がやわらかく煮込んだお粥を一さじずつ分けてくれ、私の器が空になるのを見守っていた",
"이웃집 손자가 찾아와 같이 작업대에 앉아 오래된 요령을 하나씩 가르쳤다":"隣の家の孫が訪ねてきて、一緒に作業台に座り、昔ながらのコツを一つずつ教えた",
"이웃집 전화를 빌려 장터 소식을 물어 놓고 한참 수화기를 쥔 채 바깥 마당을 내다보았다":"隣の家の電話を借りて市場の様子を聞いておき、しばらく受話器を握ったまま外の庭を眺めていた",
"이제는 눈을 감고도 순서대로 공정을 밟는다고 반장이 말했고, 내 이름이 처음으로 작업표 가운데 칸에 올랐다":"もう目をつぶっても順番どおりに工程を踏めると班長が言い、私の名前が初めて作業表の真ん中の欄に載った",
"일 생각을 잠깐 접고 놀이공원 줄에 서서, 비명 소리가 들릴 때마다 괜히 손바닥이 간지러웠다":"仕事のことをしばし忘れて遊園地の列に並び、悲鳴が聞こえるたびになんだか手のひらがむずむずした",
"일손을 하루 놓고 마루에 앉아 식은 보리차를 홀짝이며 앞산 그늘이 천천히 밭으로 내려오는 걸 보았다":"仕事を一日休んで縁側に座り、冷めた麦茶をすすりながら、前山の影がゆっくり畑に降りてくるのを眺めた",
"일요일 아침 창문을 모두 열고 이불을 털어 널었더니, 방 안에 해 냄새가 가득 찼다":"日曜の朝、窓を全部開けて布団をはたいて干すと、部屋じゅうに日なたの匂いが満ちた",
"일요일 정오 식탁에 식구들이 번갈아 앉아 국과 밥을 나르며 한 주의 이야기를 꺼내 놓았다":"日曜の正午、食卓に家族が代わる代わる座り、汁とご飯を運びながら一週間の話を切り出した",
"일을 끝내고 나서 받은 봉투에 약속한 시간의 절반만 들어 있어서, 확인해 달라는 말을 꺼내지 못했다":"仕事を終えて受け取った封筒には、約束した時間の半分しか入っておらず、確認してほしいと言い出せなかった",
"일이 끝난 저녁 동료와 길가 포장마차 의자에 앉아 김 나는 국물을 나눠 먹으며 하루를 털어 냈다":"仕事が終わった夕方、同僚と道端の屋台の椅子に座り、湯気の立つ汁を分け合って一日の疲れを払った",
"일이 늦게 끝나 식구들이 기다리다 먼저 먹은 뒤라서 혼자 식은 밥에 물을 말아 먹었다":"仕事が遅く終わり、家族は待ったあと先に食べてしまっていて、一人で冷めたご飯にお茶をかけて食べた",
