"입문":"入門",
"자식이 챙겨 준 작은 가방에 약통과 모자를 넣고, 난생처음 비행기 창가 자리에 앉아 구름을 내려다보았다":"子どもが用意してくれた小さなかばんに薬入れと帽子を入れ、生まれて初めて飛行機の窓際の席に座って雲を見下ろした",
