"장터 모임에서 새로 알게 된 아저씨가 직접 딴 과일 한 상자를 내밀며 다음 달 또 보자고 했다":"市場の集まりで知り合った男の人が、自分でもいだ果物を一箱差し出して、来月また会おうと言った",
"장터 좌판에서 산 나무 조각칼을 장롱 위에 모셔 두고, 며칠 뒤 첫 줄을 파 보았다":"市場の露店で買った木彫り用の小刀をたんすの上に大事に置いておき、数日後に最初の一筋を彫ってみた",
"장터에 가려고 짐을 싣다가 우박이 쏟아져서, 상자를 도로 안으로 들이고 하루를 접었다":"市場へ行こうと荷物を積んでいたら雹が降りだし、箱を中に戻して一日を畳んだ",
"재미있는 대목에서 정전이 되어 방이 깜깜해지는 바람에 아침까지 기다려야 했다":"面白いところで停電になって部屋が真っ暗になり、朝まで待つしかなかった",
"쟁반을 들고 가다 미끄러져 컵 몇 개를 깨뜨려서, 오늘 일당에서 깎일까 하는 생각만 했다":"お盆を持って歩いていて滑り、コップを何個か割って、今日の日当から引かれるかなとばかり考えていた",
