"저녁 공유 차량 운행을 하루 세 시간씩 해서, 지도 앱을 보며 골목을 돌고 나면 지갑이 조금 두꺼워졌다":"夕方のライドシェアを一日三時間ずつ走り、地図アプリを見ながら路地を回ると、財布が少し厚くなった",
