"저녁 먹고 말없이 둑길을 걸었고, 개구리 소리가 혼자인 걸음 사이를 채워 주었다":"夕食のあと黙って土手道を歩き、カエルの声が一人きりの足音の間を埋めてくれた",
"저녁 모임에서 새로 온 사람에게 내가 처음 만든 서투른 물건을 보여 주며, 누구나 그랬다고 말했다":"夜の集まりで新しく来た人に、私が最初に作ったぎこちない作品を見せ、誰でもそうだったと話した",
"저녁 산책길에 휴대폰을 꺼내 오랫동안 못 들은 목소리의 번호를 눌렀고 첫 신호음에 바로 받았다":"夕方の散歩道でスマホを取り出し、長いこと声を聞いていなかった人の番号を押したら、最初の呼び出し音ですぐ出てくれた",
