"저녁 상에서 마지막 남은 튀김 하나를 두고 식구와 젓가락을 맞부딪치다 둘 다 웃고 반씩 나눴다":"夕食の席で最後に残った天ぷら一つをめぐって家族と箸がぶつかり、二人とも笑って半分こした",
