"저녁 약속을 지키려고 서둘러 갔는데 막차가 끊겨 식구들은 이미 먹고 상이 치워져 있었다":"夕方の約束を守ろうと急いで行ったが終電が出たあとで、家族はもう食べ終え、膳は片付けられていた",
"저녁 어스름까지 남아 연장 하나하나를 기름 먹인 천으로 닦아 제자리에 걸어 두었다":"夕暮れまで残って道具を一つずつ油を含ませた布で拭き、元の場所に掛けておいた",
"저녁 짓는 냄새가 번질 때까지 구슬 두 알을 쥔 채 골목 끝에서 끝으로 굴리며 놀았다":"夕飯の支度の匂いが漂うまで、ビー玉を二つ握って路地の端から端まで転がして遊んだ",
"저녁마다 중고 물건을 닦아 사진을 찍어 올렸더니, 사흘 만에 첫 구매자가 나타나서 주소를 물어 왔다":"毎晩中古品を磨いて写真を撮って出品したら、三日で最初の買い手が現れ、住所を尋ねてきた",
"저녁에 공부하려던 날 갑자기 손님이 찾아와 책은 펼쳐 보지도 못한 채 밤이 깊어 버렸다":"夜に勉強しようとした日に突然お客さんが来て、本は開くこともできないまま夜が更けた",
