"저녁에 한 번 더 확인하겠다던 숫자가 아침에 보니 줄이 하나 밀려 있어서, 반나절을 거슬러 찾았다":"夜にもう一度確かめるつもりだった数字が朝見たら一行ずれていて、半日さかのぼって探した",
