"전문 자격":"専門資格",
"전문가":"専門家",
"전화기 버튼을 잘못 눌러 전혀 다른 곳에 걸려 놓고 한참 사과하느라 본래 하려던 말을 잊었다":"電話のボタンを間違えて押して全然違う所にかけてしまい、長々と謝るうちに、もともと言おうとしたことを忘れた",
