"전화를 걸자마자 현관 초인종이 울려 서둘러 끊고 나갔다가 그날은 다시 이을 틈이 없었다":"電話をかけたとたん玄関のチャイムが鳴り、慌てて切って出たら、その日はもうつなぎ直す余裕がなかった",
