"젊은 사람들 속에서도 장부를 끝까지 읽어 내려가서, 마지막에 틀린 칸 하나를 짚어 냈다":"若い人たちの中でも帳簿を最後まで読み通し、最後に間違った欄を一つ指摘した",
"젊은 직원 사이에서 가장 먼저 포장 속도를 맞춰 내자, 책임자가 시범을 한 번 보여 달라고 불렀다":"若い従業員の中でいちばん早く梱包の速さを合わせると、責任者がお手本を一度見せてほしいと呼んだ",
