"점심시간 십 분을 쪼개 건물 뒤 계단에 나가 앉았더니, 먼 산 능선이 눈에 들어와 어깨가 내려갔다":"昼休みの十分を割いて建物の裏の階段に出て座ったら、遠い山の稜線が目に入り、肩の力が抜けた",
"점심시간 옥상 한구석에서 오랜 친구에게 전화를 걸어 서로 목소리가 변했다고 농담하며 반 시간을 보냈다":"昼休みに屋上の隅から古い友人に電話をかけ、お互い声が変わったと冗談を言い合って三十分を過ごした",
"점심시간마다 후배와 구내식당 구석에서 한 과목씩 질문을 받아 주던 일이 어느새 습관이 되었다":"昼休みのたびに後輩と食堂の隅で一科目ずつ質問を受けていたことが、いつのまにか習慣になった",
"점심시간에 회사 옥상 벤치에 앉아 책 한 권을 사나흘에 걸쳐 끝내 읽어 냈다":"昼休みに会社の屋上のベンチに座り、本を一冊、三、四日かけてついに読み切った",
