"접수 창구가 이층이라 난간을 잡고 올랐는데 숨이 가빠 마감 직전에야 번호표를 받았다":"受付窓口が二階で、手すりにつかまって上がったが息が切れ、締切ぎりぎりに番号札をもらった",
