"접수창구에서 문진표를 한 장씩 채우고 키와 몸무게를 재고 나니, 마음이 오히려 가벼워졌다":"受付窓口で問診票を一枚ずつ書き、身長と体重を測ったら、かえって気持ちが軽くなった",
"접수창구에서 받은 수험표를 들고 처음 본 시험이 합격 명단에 이름 한 줄로 올라 있었다":"受付窓口でもらった受験票を持って初めて受けた試験の合格者名簿に、私の名前が一行載っていた",
