"조용한 곳을 찾아 도서관에 갔더니 단체 견학이 와서 소란스러워 한 장도 못 넘겼다":"静かな場所を探して図書館に行ったら団体見学が来ていて騒がしく、一ページもめくれなかった",
"조카 손을 잡고 가서 고른 그림책을, 아이보다 내가 먼저 끝까지 읽어 버렸다":"甥や姪の手を引いて行って選んだ絵本を、子どもより先に私が最後まで読んでしまった",
"조카네 집 책꽂이에서 꺼낸 그림책 한 권에, 나도 모르게 소파에 앉아 한 시간이 지나갔다":"甥の家の本棚から出した絵本一冊に、知らないうちにソファに座って一時間が過ぎた",
"조카들이 가져온 레고 상자를 쏟아 놓고, 설명서도 안 보고 성을 올리느라 저녁밥이 식었다":"甥や姪が持ってきたレゴの箱をひっくり返し、説明書も見ずに城を組み上げているうちに夕ご飯が冷めた",
"조회가 끝난 뒤 후배의 서투른 작업을 같이 들여다보며, 어디에서 힘을 빼야 하는지 손끝으로 짚어 보여 주었다":"朝礼のあと後輩のぎこちない作業を一緒にのぞき込み、どこで力を抜けばいいか指先で示してやった",
"졸다가 작업대 위 도면에 커피를 쏟아서, 번진 얼룩 위로 새 종이를 붙이느라 새벽이 다 갔다":"うとうとして作業台の上の図面にコーヒーをこぼし、にじんだ染みの上に新しい紙を貼るうちに夜が明けた",
"좁은 부엌 식탁에 식구가 다닥다닥 붙어 앉아 김 나는 면을 후루룩 소리 내며 먹었다":"狭い台所のテーブルに家族がぎゅうぎゅうに座り、湯気の立つ麺をずるずる音を立ててすすった",
"좁은 집 베란다 문을 열어 놓고 식구가 둘러앉아 배달 온 음식을 펼쳐 놓고 옆자리 접시까지 서로 밀어 주었다":"狭い家のベランダの戸を開け放って家族で輪になり、出前を広げて、隣の皿まで互いに押しやった",
